// lib/creator-context.ts
function text2(v, maxLen = 300) {
  if (v == null) return "";
  const s = Array.isArray(v) ? v.filter(Boolean).join("\u3001") : String(v);
  const t = s.trim();
  if (!t) return "";
  return t.length > maxLen ? t.slice(0, maxLen) + "\u2026" : t;
}
function line(label, value, maxLen = 300) {
  const t = text2(value, maxLen);
  return t ? `- **${label}**\uFF1A${t}` : null;
}
var join = (lines) => lines.filter(Boolean).join("\n");
function describeExecutionConstraints(p) {
  const gear = text2(p?.equipment, 200);
  const team = text2(p?.team_structure, 100);
  const place = text2(p?.shooting_location, 150);
  if (!gear && !team) {
    return `- \u62CD\u6444\u6210\u672C\u8981\u4F4E\uFF1A\u624B\u673A\u5373\u53EF\uFF0C\u4E0D\u9700\u8981\u4E13\u4E1A\u8BBE\u5907
- \u7B80\u5355\u6613\u4E0A\u624B\uFF1A\u4E00\u4E2A\u4EBA\u5C31\u80FD\u62CD\uFF0C\u4E0D\u9700\u8981\u56E2\u961F\u6216\u6F14\u5458
- \u573A\u666F\u8981\u6C42\uFF1A\u65E5\u5E38\u573A\u666F\uFF08\u5E97\u5185/\u5BB6\u91CC\uFF09\uFF0C\u907F\u514D\u51CC\u6668\u62CD\u6444\u3001\u591A\u573A\u666F\u5207\u6362
- \u9053\u5177\u8981\u6C42\uFF1A\u65E5\u5E38\u9053\u5177\uFF0C\u907F\u514D\u590D\u6742\u9053\u5177`;
  }
  return join([
    "- \u9009\u9898\u5FC5\u987B\u843D\u5728\u8FD9\u4E2A\u8D26\u53F7\u7684\u771F\u5B9E\u62CD\u6444\u80FD\u529B\u4E4B\u5185\uFF1A",
    line("  \u53EF\u7528\u8BBE\u5907", gear),
    line("  \u56E2\u961F\u89C4\u6A21", team),
    line("  \u53EF\u7528\u573A\u5730", place),
    "- \u5668\u6750\u6E05\u5355\u91CC\u6CA1\u6709\u7684\u4E1C\u897F\u4E0D\u8981\u5047\u8BBE\u5B83\u5B58\u5728\uFF1B\u573A\u5730\u6CA1\u5199\u5230\u7684\u4E0D\u8981\u8BBE\u8BA1\u6210\u5916\u62CD",
    team && !/1人|单人|一个人|个人/.test(team) ? "- \u6709\u56E2\u961F\u5C31\u53EF\u4EE5\u51FA\u955C+\u638C\u673A\u5206\u5DE5\uFF0C\u9700\u8981\u4E24\u4E2A\u4EBA\u914D\u5408\u7684\u9009\u9898\u662F\u53EF\u4EE5\u505A\u7684" : "- \u53EA\u6709\u4E00\u4E2A\u4EBA\uFF0C\u9700\u8981\u4ED6\u4EBA\u914D\u5408\u51FA\u955C\u7684\u9009\u9898\u4E0D\u8981\u51FA",
    "- \u4ECD\u7136\u8981\u53EF\u6267\u884C\uFF1A\u907F\u514D\u51CC\u6668\u62CD\u6444\u3001\u9700\u8981\u8BF7\u6F14\u5458\u3001\u8DE8\u591A\u4E2A\u573A\u5730\u7684\u9009\u9898"
  ]);
}

