function viralElementPrompt(ids) {
  const picked = ids.map(viralElementById).filter((e) => !!e);
  if (picked.length === 0) return "";
  const lines = [
    "\u3010\u516B\u5927\u7206\u6B3E\u5143\u7D20\u3011\u9009\u4E2D\u4EE5\u4E0B\u89D2\u5EA6\uFF0C\u6309\u7ED9\u5B9A\u53E5\u5F0F\u51FA\u9009\u9898\uFF1A",
    "",
    ...picked.flatMap((e) => [
      // 用括号而不是破折号：hook 本身就含破折号，两个撞在一起读不清
      `\u25B8 ${e.name}\uFF08${e.hook}\uFF09`,
      `  \u53EF\u5957\u53E5\u5F0F\uFF1A${e.patterns.join(" / ")}`
    ]),
    "",
    "\u8981\u6C42\uFF1A",
    "- \u6BCF\u6761\u9009\u9898\u5FC5\u987B\u843D\u5728\u4E0A\u9762\u67D0\u4E00\u4E2A\u53E5\u5F0F\u4E0A\uFF0C\u628A X \u6362\u6210\u672C\u884C\u4E1A\u7684\u5177\u4F53\u4E1C\u897F",
    "- \u53E5\u5F0F\u662F\u77E5\u8BC6\u5E93\u7ED9\u5B9A\u7684\uFF0C\u4E0D\u8981\u81EA\u5DF1\u53E6\u9020\u4E00\u5957",
    "- \u6BCF\u6761\u9009\u9898\u540E\u6807\u6CE8\u7528\u7684\u662F\u54EA\u4E2A\u5143\u7D20\u3001\u5957\u7684\u54EA\u4E2A\u53E5\u5F0F"
  ];
  return lines.join("\n");
}

